import React, { ReactElement } from 'react';
import { isElement } from 'react-is';

import { Threshold } from '../slots/Threshold.js';
import { ThresholdLegend } from '../slots/ThresholdLegend.js';
import { ThresholdMetadata } from '../types/meter-bar-chart-internal.js';

export const getThresholdData = (children: ReactElement) => {
  const thresholdConfig: ThresholdMetadata = { data: [] };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case Threshold: {
          const dataArray = thresholdConfig.data ?? [];
          dataArray.push(child.props);
          thresholdConfig.data = dataArray;
          break;
        }
        case ThresholdLegend:
          thresholdConfig.legend = true;
          break;
      }
    }
  });

  return thresholdConfig;
};
